def to_float_tensor(numpy_array: np.ndarray) ->torch.Tensor:
    if numpy_array.dtype != np.float32:
        numpy_array = numpy_array.astype(np.float32)
    return torch.from_numpy(numpy_array)


def to_numpy(float_tensor: torch.Tensor, target_shape: list, target_dtype:
    np.dtype) ->np.ndarray:
    numpy_array = float_tensor.detach().cpu().numpy()
    if target_dtype != np.float32:
        numpy_array = numpy_array.astype(target_dtype)
    return numpy_array
